package com.cloudkit.storage

import java.io.File
import java.nio.file.Path
import java.nio.file.Paths
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.CountDownLatch

data class BucketConfig(
    val basePath: String,
    val allowListing: Boolean = false,
    val publicPrefix: String = "/public"
)

class StorageSDK(private val config: BucketConfig) {
    private val shutdownRequested = AtomicBoolean(false)
    private val activeRequests = ConcurrentHashMap<String, Long>()
    private val shutdownLatch = CountDownLatch(1)
    private val sanitizedBase: Path = Paths.get(config.basePath).toAbsolutePath().normalize()

    fun initiateGracefulShutdown() {
        shutdownRequested.set(true)
        Thread {
            while (activeRequests.isNotEmpty()) {
                Thread.sleep(100)
            }
            shutdownLatch.countDown()
        }.start()
    }

    fun awaitShutdown() {
        shutdownLatch.await()
    }

    fun listObjects(requestPath: String, requestId: String): Result<List<String>> {
        if (shutdownRequested.get()) {
            return Result.failure(IllegalStateException("Service shutting down"))
        }
        activeRequests[requestId] = System.currentTimeMillis()
        try {
            return performListing(requestPath)
        } finally {
            activeRequests.remove(requestId)
        }
    }

    private fun performListing(requestPath: String): Result<List<String>> {
        val normalizedRequest = normalizePath(requestPath)
        if (!isPathAuthorized(normalizedRequest)) {
            return Result.failure(SecurityException("Access denied"))
        }
        val targetDir = resolveTargetDirectory(normalizedRequest)
        return executeListing(targetDir)
    }

    private fun normalizePath(input: String): String {
        // Remove null bytes and normalize separators
        val cleaned = input.replace("\u0000", "").replace("\\", "/")
        // Collapse multiple slashes
        val collapsed = cleaned.replace(Regex("/+"), "/")
        // Remove trailing slash
        return collapsed.trimEnd('/')
    }

    private fun isPathAuthorized(normalizedPath: String): Boolean {
        if (config.allowListing) return true
        // Only allow listing under public prefix when listing is disabled
        return normalizedPath.startsWith(config.publicPrefix)
    }

    private fun resolveTargetDirectory(normalizedPath: String): File {
        val resolved = sanitizedBase.resolve(normalizedPath.removePrefix("/")).normalize()
        // Security check: ensure resolved path is within base
        if (!resolved.startsWith(sanitizedBase)) {
            throw SecurityException("Path traversal detected")
        }
        return resolved.toFile()
    }

    private fun executeListing(targetDir: File): Result<List<String>> {
        if (!targetDir.exists() || !targetDir.isDirectory) {
            return Result.failure(NoSuchFileException(targetDir))
        }
        val entries = targetDir.listFiles()?.map { file ->
            buildEntryDescriptor(file)
        } ?: emptyList()
        return Result.success(entries)
    }

    private fun buildEntryDescriptor(file: File): String {
        val relativePath = sanitizedBase.relativize(file.toPath()).toString()
        val fileType = if (file.isDirectory) "dir" else "file"
        val size = if (file.isFile) file.length() else 0L
        return "$relativePath|$fileType|$size"
    }
}

class StorageGateway(private val configs: Map<String, BucketConfig>) {
    private val sdkInstances = ConcurrentHashMap<String, StorageSDK>()

    fun getOrCreateSDK(bucketName: String): StorageSDK? {
        val config = configs[bucketName] ?: return null
        return sdkInstances.getOrPut(bucketName) { StorageSDK(config) }
    }

    fun handleListRequest(bucketName: String, path: String, requestId: String): Result<List<String>> {
        val sdk = getOrCreateSDK(bucketName)
            ?: return Result.failure(IllegalArgumentException("Unknown bucket: $bucketName"))
        return sdk.listObjects(path, requestId)
    }

    fun shutdownAll() {
        sdkInstances.values.forEach { it.initiateGracefulShutdown() }
        sdkInstances.values.forEach { it.awaitShutdown() }
    }
}

fun createDefaultGateway(): StorageGateway {
    val configs = mapOf(
        "user-uploads" to BucketConfig(
            basePath = "/var/storage/uploads",
            allowListing = false,
            publicPrefix = "/public"
        ),
        "static-assets" to BucketConfig(
            basePath = "/var/storage/static",
            allowListing = true
        )
    )
    return StorageGateway(configs)
}
